{"file_text": "namespace RecipeHub.Data;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
            Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes over the dough.\n4. Tear mozzarella and distribute evenly.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil."
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nTomato sauce\nHeavy cream\nGarlic\nGinger\nOnion",
            Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or pan-sear chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomato sauce and simmer 15 minutes.\n5. Stir in cream and spices.\n6. Add chicken and simmer 10 more minutes."
        },
        new()
        {
            Id = 3, Title = "Beef Tacos", Category = "Mexican",
            Ingredients = "Ground beef\nTaco shells\nLettuce\nTomato\nCheddar cheese\nSour cream\nTaco seasoning\nOnion",
            Steps = "1. Brown ground beef with diced onion.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm taco shells in the oven.\n4. Fill shells with beef mixture.\n5. Top with lettuce, tomato, cheese, and sour cream."
        },
        new()
        {
            Id = 4, Title = "Pad Thai", Category = "Thai",
            Ingredients = "Rice noodles\nShrimp\nEggs\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar",
            Steps = "1. Soak rice noodles in warm water for 30 minutes.\n2. Make sauce: mix tamarind paste, fish sauce, and sugar.\n3. Stir-fry shrimp until pink, set aside.\n4. Scramble eggs in the same pan.\n5. Add drained noodles and sauce, toss to coat.\n6. Add shrimp, bean sprouts, and green onions.\n7. Serve with crushed peanuts and lime wedges."
        },
        new()
        {
            Id = 5, Title = "Spaghetti Carbonara", Category = "Italian",
            Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
            Steps = "1. Cook spaghetti in salted boiling water.\n2. Crisp guanciale in a pan over medium heat.\n3. Whisk eggs with grated Pecorino and pepper.\n4. Drain pasta, reserving some pasta water.\n5. Toss hot pasta with guanciale off heat.\n6. Add egg mixture and toss quickly, adding pasta water to create a creamy sauce."
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic",
            Steps = "1. Halve and pit avocados, scoop into a bowl.\n2. Mash to desired consistency.\n3. Stir in diced onion, tomato, jalapeño, and cilantro.\n4. Add lime juice, minced garlic, and salt.\n5. Serve immediately with tortilla chips."
        },
        new()
        {
            Id = 7, Title = "Green Curry", Category = "Thai",
            Ingredients = "Coconut milk\nGreen curry paste\nChicken thighs\nBamboo shoots\nThai basil\nFish sauce\nSugar\nBell pepper\nEggplant",
            Steps = "1. Heat coconut cream (thick top of can) in a pot.\n2. Fry curry paste in the cream for 2 minutes.\n3. Add chicken and cook until no longer pink.\n4. Pour in remaining coconut milk.\n5. Add vegetables and simmer 15 minutes.\n6. Season with fish sauce and sugar.\n7. Stir in Thai basil before serving."
        },
        new()
        {
            Id = 8, Title = "Butter Chicken", Category = "Indian",
            Ingredients = "Chicken thighs\nButter\nTomato puree\nHeavy cream\nGaram masala\nChili powder\nGarlic\nGinger\nFenugreek leaves",
            Steps = "1. Marinate chicken in yogurt and spices.\n2. Grill or bake chicken until cooked.\n3. Melt butter, sauté garlic and ginger.\n4. Add tomato puree and spices, simmer 20 minutes.\n5. Stir in cream and fenugreek leaves.\n6. Add chicken and simmer 10 minutes.\n7. Serve with naan or basmati rice."
        },
    ];

    private int _nextId = 9;

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }
}
