﻿@page "/"

@using RecipeHub.Data
@inject RecipeService RecipeService

<PageTitle>RecipeHub - Home</PageTitle>

<h1>🍳 Welcome to RecipeHub</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<div class="row mt-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col-md-3 mb-4">
            <div class="card h-100 shadow-sm">
                <div class="card-body text-center">
                    <h4 class="card-title">@CategoryIcon(category) @category</h4>
                    <p class="text-muted">@RecipeService.GetByCategory(category).Count recipes</p>
                    <a href="recipes/@category" class="btn btn-outline-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<div class="mt-4 p-4 bg-light rounded">
    <h3>📝 Have a recipe to share?</h3>
    <p>Join our community and submit your favorite recipes!</p>
    <a href="submit" class="btn btn-success">Submit a Recipe</a>
</div>

@code {
    private static string CategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        _ => "🍽️"
    };
}

toolArgs.file_text:
@using RecipeHub.Data
@inject RecipeService RecipeService

@if (submitted)
{
    <p class="text-success">
        ✅ Thanks for rating! You gave this recipe <strong>@submittedRating</strong> star@(submittedRating == 1 ? "" : "s").
    </p>
}
else
{
    <div class="d-flex align-items-center gap-1">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <button class="btn btn-link p-0 fs-3 text-decoration-none"
                    title="Rate @star star@(star == 1 ? "" : "s")"
                    @onclick="() => SubmitRating(star)"
                    @onmouseover="() => hoverRating = star"
                    @onmouseout="() => hoverRating = 0">
                @(star <= (hoverRating > 0 ? hoverRating : selectedRating) ? "⭐" : "☆")
            </button>
        }
        @if (selectedRating > 0)
        {
            <span class="ms-2 text-muted">@selectedRating star@(selectedRating == 1 ? "" : "s")</span>
        }
    </div>
}

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedRating;
    private int hoverRating;
    private bool submitted;
    private int submittedRating;

    private void SubmitRating(int stars)
    {
        selectedRating = stars;
        submittedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

